### src/main/java/com/example/booking/service/ServiceService.java
```java
package com.example.booking.service;

import com.example.booking.dto.*;
import com.example.booking.exception.ResourceNotFoundException;
import com.example.booking.model.Service;
import com.example.booking.model.User;
import com.example.booking.repository.ServiceRepository;
import com.example.booking.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Transactional
public class ServiceService {

    private final ServiceRepository serviceRepository;
    private final UserRepository userRepository;

    @Transactional(readOnly = true)
    public Page<ServiceResponse> findAll(String search, Pageable pageable) {
        Page<Service> page;
        if (search != null && !search.isEmpty()) {
            page = serviceRepository.findByNameContainingIgnoreCase(search, pageable);
        } else {
            page = serviceRepository.findAll(pageable);
        }
        return page.map(this::toResponse);
    }

    @Transactional(readOnly = true)
    public ServiceResponse findById(UUID id) {
        return serviceRepository.findById(id)
                .map(this::toResponse)
                .orElseThrow(() -> new ResourceNotFoundException("Service not found"));
    }

    public ServiceResponse create(ServiceRequest request, String username) {
        User user = userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));

        Service service = Service.builder()
                .name(request.getName())
                .description(request.getDescription())
                .status(Service.Status.ACTIVE)
                .createdBy(user)
                .build();

        return toResponse(serviceRepository.save(service));
    }

    public ServiceResponse update(UUID id, ServiceRequest request) {
        Service service = serviceRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Service not found"));

        service.setName(request.getName());
        service.setDescription(request.getDescription());
        if (request.getStatus() != null) {
            service.setStatus(request.getStatus());
        }

        return toResponse(serviceRepository.save(service));
    }

    public void delete(UUID id) {
        if (!serviceRepository.existsById(id)) {
            throw new ResourceNotFoundException("Service not found");
        }
        serviceRepository.deleteById(id);
    }

    private ServiceResponse toResponse(Service service) {
        return ServiceResponse.builder()
                .id(service.getId())
                .name(service.getName())
                .description(service.getDescription())
                .status(service.getStatus())
                .createdAt(service.getCreatedAt())
                .build();
    }
}
