final usersProvider = StateNotifierProvider<UserNotifier, AsyncValue<List<User>>>((ref) {
  return UserNotifier(ref);
});

class UserNotifier extends StateNotifier<AsyncValue<List<User>>> {
  final Ref _ref;

  UserNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadUsers();
  }

  Future<void> loadUsers() async {
    state = const AsyncValue.loading();
    try {
      final getUsers = _ref.read(getUsersUseCaseProvider);
      final users = await getUsers();
      state = AsyncValue.data(users);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createUser(String name, String description) async {
    try {
      final createUser = _ref.read(createUserUseCaseProvider);
      final newUser = await createUser(name, description);
      state = AsyncValue.data([...state.value ?? [], newUser]);
    } catch (e) {
      rethrow;
    }
  }
}
