```dart
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/product.dart';
import '../../domain/usecases/get_products.dart';
import '../../domain/usecases/create_product.dart';

final productsProvider = StateNotifierProvider<ProductNotifier, AsyncValue<List<Product>>>((ref) {
  return ProductNotifier(ref);
});

class ProductNotifier extends StateNotifier<AsyncValue<List<Product>>> {
  final Ref _ref;

  ProductNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadProducts();
  }

  Future<void> loadProducts() async {
    state = const AsyncValue.loading();
    try {
      final getProducts = _ref.read(getProductsUseCaseProvider);
      final products = await getProducts();
      state = AsyncValue.data(products);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createProduct(String name, String description) async {
    try {
      final createProduct = _ref.read(createProductUseCaseProvider);
      final newProduct = await createProduct(name, description);
      state = AsyncValue.data([...state.value ?? [], newProduct]);
    } catch (e) {
      rethrow;
    }
  }
}
