```dart
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/course.dart';
import '../../domain/usecases/get_courses.dart';
import '../../domain/usecases/create_course.dart';

final coursesProvider = StateNotifierProvider<CourseNotifier, AsyncValue<List<Course>>>((ref) {
  return CourseNotifier(ref);
});

class CourseNotifier extends StateNotifier<AsyncValue<List<Course>>> {
  final Ref _ref;

  CourseNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadCourses();
  }

  Future<void> loadCourses() async {
    state = const AsyncValue.loading();
    try {
      final getCourses = _ref.read(getCoursesUseCaseProvider);
      final courses = await getCourses();
      state = AsyncValue.data(courses);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createCourse(String name, String description) async {
    try {
      final createCourse = _ref.read(createCourseUseCaseProvider);
      final newCourse = await createCourse(name, description);
      state = AsyncValue.data([...state.value ?? [], newCourse]);
    } catch (e) {
      rethrow;
    }
  }
}
