```java
package com.example.crm.service;

import com.example.crm.dto.*;
import com.example.crm.exception.ResourceNotFoundException;
import com.example.crm.model.Contact;
import com.example.crm.model.User;
import com.example.crm.repository.ContactRepository;
import com.example.crm.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Transactional
public class ContactService {

    private final ContactRepository contactRepository;
    private final UserRepository userRepository;

    @Transactional(readOnly = true)
    public Page<ContactResponse> findAll(String search, Pageable pageable) {
        Page<Contact> page;
        if (search != null && !search.isEmpty()) {
            page = contactRepository.findByNameContainingIgnoreCase(search, pageable);
        } else {
            page = contactRepository.findAll(pageable);
        }
        return page.map(this::toResponse);
    }

    @Transactional(readOnly = true)
    public ContactResponse findById(UUID id) {
        return contactRepository.findById(id)
                .map(this::toResponse)
                .orElseThrow(() -> new ResourceNotFoundException("Contact not found"));
    }

    public ContactResponse create(ContactRequest request, String username) {
        User user = userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));

        Contact contact = Contact.builder()
                .name(request.getName())
                .description(request.getDescription())
                .status(Contact.Status.ACTIVE)
                .createdBy(user)
                .build();

        return toResponse(contactRepository.save(contact));
    }

    public ContactResponse update(UUID id, ContactRequest request) {
        Contact contact = contactRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Contact not found"));

        contact.setName(request.getName());
        contact.setDescription(request.getDescription());
        if (request.getStatus() != null) {
            contact.setStatus(request.getStatus());
        }

        return toResponse(contactRepository.save(contact));
    }

    public void delete(UUID id) {
        if (!contactRepository.existsById(id)) {
            throw new ResourceNotFoundException("Contact not found");
        }
        contactRepository.deleteById(id);
    }

    private ContactResponse toResponse(Contact contact) {
        return ContactResponse.builder()
                .id(contact.getId())
                .name(contact.getName())
                .description(contact.getDescription())
                .status(contact.getStatus())
                .createdAt(contact.getCreatedAt())
                .build();
    }
}
