```dart
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/contact.dart';
import '../../domain/usecases/get_contacts.dart';
import '../../domain/usecases/create_contact.dart';

final contactsProvider = StateNotifierProvider<ContactNotifier, AsyncValue<List<Contact>>>((ref) {
  return ContactNotifier(ref);
});

class ContactNotifier extends StateNotifier<AsyncValue<List<Contact>>> {
  final Ref _ref;

  ContactNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadContacts();
  }

  Future<void> loadContacts() async {
    state = const AsyncValue.loading();
    try {
      final getContacts = _ref.read(getContactsUseCaseProvider);
      final contacts = await getContacts();
      state = AsyncValue.data(contacts);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createContact(String name, String description) async {
    try {
      final createContact = _ref.read(createContactUseCaseProvider);
      final newContact = await createContact(name, description);
      state = AsyncValue.data([...state.value ?? [], newContact]);
    } catch (e) {
      rethrow;
    }
  }
