```java
package com.example.lms.service;

import com.example.lms.dto.*;
import com.example.lms.exception.ResourceNotFoundException;
import com.example.lms.model.Course;
import com.example.lms.model.User;
import com.example.lms.repository.CourseRepository;
import com.example.lms.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Transactional
public class CourseService {

    private final CourseRepository courseRepository;
    private final UserRepository userRepository;

    @Transactional(readOnly = true)
    public Page<CourseResponse> findAll(String search, Pageable pageable) {
        Page<Course> page;
        if (search != null && !search.isEmpty()) {
            page = courseRepository.findByNameContainingIgnoreCase(search, pageable);
        } else {
            page = courseRepository.findAll(pageable);
        }
        return page.map(this::toResponse);
    }

    @Transactional(readOnly = true)
    public CourseResponse findById(UUID id) {
        return courseRepository.findById(id)
                .map(this::toResponse)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found"));
    }

    public CourseResponse create(CourseRequest request, String username) {
        User user = userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));

        Course course = Course.builder()
                .name(request.getName())
                .description(request.getDescription())
                .status(Course.Status.ACTIVE)
                .createdBy(user)
                .build();

        return toResponse(courseRepository.save(course));
    }

    public CourseResponse update(UUID id, CourseRequest request) {
        Course course = courseRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Course not found"));

        course.setName(request.getName());
        course.setDescription(request.getDescription());
        if (request.getStatus() != null) {
            course.setStatus(request.getStatus());
        }

        return toResponse(courseRepository.save(course));
    }

    public void delete(UUID id) {
        if (!courseRepository.existsById(id)) {
            throw new ResourceNotFoundException("Course not found");
        }
        courseRepository.deleteById(id);
    }

    private CourseResponse toResponse(Course course) {
        return CourseResponse.builder()
                .id(course.getId())
                .name(course.getName())
                .description(course.getDescription())
                .status(course.getStatus())
                .createdAt(course.getCreatedAt())
                .build();
    }
}
