```java
package com.example.blog.service;

import com.example.blog.dto.*;
import com.example.blog.exception.ResourceNotFoundException;
import com.example.blog.model.Post;
import com.example.blog.model.User;
import com.example.blog.repository.PostRepository;
import com.example.blog.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Transactional
public class PostService {

    private final PostRepository postRepository;
    private final UserRepository userRepository;

    @Transactional(readOnly = true)
    public Page<PostResponse> findAll(String search, Pageable pageable) {
        Page<Post> page;
        if (search != null && !search.isEmpty()) {
            page = postRepository.findByNameContainingIgnoreCase(search, pageable);
        } else {
            page = postRepository.findAll(pageable);
        }
        return page.map(this::toResponse);
    }

    @Transactional(readOnly = true)
    public PostResponse findById(UUID id) {
        return postRepository.findById(id)
                .map(this::toResponse)
                .orElseThrow(() -> new ResourceNotFoundException("Post not found"));
    }

    public PostResponse create(PostRequest request, String username) {
        User user = userRepository.findByEmail(username)
                .orElseThrow(() -> new ResourceNotFoundException("User not found"));

        Post post = Post.builder()
                .name(request.getName())
                .description(request.getDescription())
                .status(Post.Status.ACTIVE)
                .createdBy(user)
                .build();

        return toResponse(postRepository.save(post));
    }

    public PostResponse update(UUID id, PostRequest request) {
        Post post = postRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("Post not found"));

        post.setName(request.getName());
        post.setDescription(request.getDescription());
        if (request.getStatus() != null) {
            post.setStatus(request.getStatus());
        }

        return toResponse(postRepository.save(post));
    }

    public void delete(UUID id) {
        if (!postRepository.existsById(id)) {
            throw new ResourceNotFoundException("Post not found");
        }
        postRepository.deleteById(id);
    }

    private PostResponse toResponse(Post post) {
        return PostResponse.builder()
                .id(post.getId())
                .name(post.getName())
                .description(post.getDescription())
                .status(post.getStatus())
                .createdAt(post.getCreatedAt())
                .build();
    }
}
