### lib/features/post/presentation/providers/post_provider.dart
```dart
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/post.dart';
import '../../domain/usecases/get_posts.dart';
import '../../domain/usecases/create_post.dart';

final postsProvider = StateNotifierProvider<PostNotifier, AsyncValue<List<Post>>>((ref) {
  return PostNotifier(ref);
});

class PostNotifier extends StateNotifier<AsyncValue<List<Post>>> {
  final Ref _ref;

  PostNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadPosts();
  }

  Future<void> loadPosts() async {
    state = const AsyncValue.loading();
    try {
      final getPosts = _ref.read(getPostsUseCaseProvider);
      final posts = await getPosts();
      state = AsyncValue.data(posts);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createPost(String name, String description) async {
    try {
      final createPost = _ref.read(createPostUseCaseProvider);
      final newPost = await createPost(name, description);
      state = AsyncValue.data([...state.value ?? [], newPost]);
    } catch (e) {
      rethrow;
    }
  }
}
```

