  return ServiceNotifier(ref);
});

class ServiceNotifier extends StateNotifier<AsyncValue<List<Service>>> {
  final Ref _ref;

  ServiceNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadServices();
  }

  Future<void> loadServices() async {
    state = const AsyncValue.loading();
    try {
      final getServices = _ref.read(getServicesUseCaseProvider);
      final services = await getServices();
      state = AsyncValue.data(services);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createService(String name, String description) async {
    try {
      final createService = _ref.read(createServiceUseCaseProvider);
      final newService = await createService(name, description);
      state = AsyncValue.data([...state.value ?? [], newService]);
    } catch (e) {
      rethrow;
    }
  }
}
